CREATE TABLE "public"."role" (
  "id_rol"     integer               GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_rol" character varying(60) NOT NULL,
  CONSTRAINT "role_nombre_rol_key" UNIQUE (nombre_rol),
  CONSTRAINT "role_pkey" PRIMARY KEY (id_rol)
);

ALTER TABLE "public"."role"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON SEQUENCE "public"."role_id_rol_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."role_id_rol_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."role_id_rol_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."role_id_rol_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."role_id_rol_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."role_id_rol_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."role_id_rol_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."role_id_rol_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."role" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."role" TO "service_role";

REVOKE ALL ON TABLE "public"."role" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."role" TO "postgres";
